	private static TupleExpr unsupportedBoundary(PackedQuery query, int payloadId) {
		requirePayload(query, payloadId, PackedPayloadOp.UNSUPPORTED);
		throw UnsupportedCascadesOperatorException.packedBoundary(
				(String) query.objectValue(query.payloadPrimary(payloadId)),
				(String) query.objectValue(query.payloadSecondary(payloadId)));
	}

	private static void verifyDependentJoinCostingContext(PackedPlanRecipe recipe, int recipeId) {
		if (recipe.operatorTag(recipeId) != PackedRelOp.JOIN || recipe.childCount(recipeId) != 2) {
			return;
		}
		PackedCostingTrace trace = recipe.costingTrace();
		int parentEventId = recipe.costEventId(recipeId);
		int rightRecipeId = recipe.childRecipeId(recipeId, 1);
		int rightEventId = recipe.costEventId(rightRecipeId);
		if (parentEventId <= 0 || rightEventId <= 0
				|| trace.phase(parentEventId) != PackedCostingPhase.PHYSICAL_JOIN
				|| trace.phase(rightEventId) != PackedCostingPhase.PREFIX_EXTENSION
				|| Double.compare(trace.prefixRows(parentEventId), trace.prefixRows(rightEventId)) == 0) {
			return;
		}
		throw new PackedMemoInvariantException("materialized dependent join has mismatched costing contexts: recipe="
				+ recipeId + ", implementation=" + recipe.implementationForm(recipeId) + ", parentEvent="
				+ parentEventId + ", parentPrefixRows=" + trace.prefixRows(parentEventId) + ", rightRecipe="
				+ rightRecipeId + ", rightEvent=" + rightEventId + ", rightPrefixRows="
				+ trace.prefixRows(rightEventId));
	}

	private static Filter semiAntiJoin(PackedQuery query, PackedPlanRecipe recipe, int nodeId) {
		int payloadId = requirePayload(query, relPayload(query, recipe, nodeId), PackedPayloadOp.SEMI_ANTI_JOIN);
		Filter filter = new Filter(
				relation(query, recipe, relChild(query, recipe, nodeId, 0)),
				scalar(query, recipe, nodeId, query.payloadPrimary(payloadId)));
		String algorithm = switch (query.payloadFlags(payloadId)) {
		case PackedQueryView.SEMI_ANTI_STREAMING -> "streaming-correlated";
		case PackedQueryView.SEMI_ANTI_MEMOIZED -> "memoized-correlated";
		case PackedQueryView.SEMI_ANTI_MATERIALIZED -> "materialized-hash";
		default -> throw new PackedMemoInvariantException("unknown packed semi/anti algorithm");
		};
		String kind = switch (query.payloadSecondary(payloadId)) {
		case PackedQueryView.SEMI_ANTI_EXISTS -> "exists";
		case PackedQueryView.SEMI_ANTI_NOT_EXISTS -> "not-exists";
		case PackedQueryView.SEMI_ANTI_MINUS_ASSURED_SHARED -> "minus-assured-shared";
		default -> throw new PackedMemoInvariantException("unknown packed semi/anti semantic kind");
		};
		filter.setStringMetricPlanned("optimizer.filterAlgorithmHint", algorithm);
		filter.setStringMetricPlanned("optimizer.semiAntiAlgorithm", algorithm);
		filter.setStringMetricPlanned("optimizer.semiAntiKind", kind);
		return filter;
	}

